{
  "id": "V025",
  "checks": [
    {
      "field": "purpose",
      "score": 2,
      "reason": "영어 독자가 이해할 수 있는 기업 소식 기사 번역 목적이 보존됨."
    },
    {
      "field": "action",
      "score": 2,
      "reason": "번역문 작성, 고유명사·수치 확인, 원문 대조 검토와 게시 결정이 포함됨."
    },
    {
      "field": "object",
      "score": 2,
      "reason": "국내에서 작성한 기업 소식 기사와 그 번역문이 보존됨."
    },
    {
      "field": "input",
      "score": 2,
      "reason": "한국어 기사 원문이 입력으로 명시됨."
    },
    {
      "field": "output",
      "score": 2,
      "reason": "영어 독자가 이해할 수 있는 번역문이 결과물로 명시됨."
    },
    {
      "field": "constraints",
      "score": 2,
      "reason": "원문에 없는 인용이나 성과를 추가하지 않는 제약이 보존됨."
    },
    {
      "field": "no_added_functions",
      "score": 2,
      "reason": "원문에 없는 기능이나 수행을 추가하지 않음."
    },
    {
      "field": "roles",
      "score": 2,
      "reason": "해외 배포 담당자의 번역·확인과 편집자의 검토·게시 결정 역할이 보존됨."
    }
  ],
  "issues": [],
  "permission_interpretation": "게시 결정은 편집자의 권한으로 제시되며, AI가 게시하거나 편집자가 매번 반드시 게시한다는 뜻은 아님."
}
